import{_ as s,o as t,a as e,b as l}from"./app.C41L12d5.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"同步控制","link":"/api/SIMD-API/basic_api/sync_control/sync_control"},{"text":"核间同步","link":"/api/SIMD-API/basic_api/sync_control/inter_core_sync/inter_core_sync"},{"text":"NotifyNextBlock","link":"/api/SIMD-API/basic_api/sync_control/inter_core_sync/NotifyNextBlock"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/sync_control/inter_core_sync/NotifyNextBlock.md","filePath":"api/SIMD-API/basic_api/sync_control/inter_core_sync/NotifyNextBlock.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788159000000}'),i={name:"api/SIMD-API/basic_api/sync_control/inter_core_sync/NotifyNextBlock.md"};function n(c,a,o,p,r,d){return t(),e("div",null,[...a[0]||(a[0]=[l(`<div><article class="markdown-body"><h1>NotifyNextBlock<span id="ZH-CN_TOPIC_0000001723989788"></span></h1><h2 id="产品支持情况">产品支持情况<span id="section1550532418810"></span><a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<span id="section618mcpsimp"></span><a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;basic_api/kernel_operator_determine_compute_sync_intf.h&quot;</code>。</p><p>WaitPreBlock和NotifyNextBlock是核间同步控制接口。NotifyNextBlock通过写全局内存来通知其他核当前核已执行完成，其他核可以继续往下执行；WaitPreBlock通过读取全局内存，判断当前核是否可以继续往下执行。</p><p>WaitPreBlock和NotifyNextBlock必须与<a href="InitDetermineComputeWorkspace.html#">InitDetermineComputeWorkspace</a>接口配合使用，这三个接口组合使用能够确保多个AIV核严格按照blockIdx的升序执行，适用于要求确定性计算的场景，确定性计算的具体含义请参考<a href="../../atomic_operations/key_features.html">确定性计算</a>。</p><h2 id="函数原型">函数原型<span id="section620mcpsimp"></span><a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">NotifyNextBlock</span><span class="p">(</span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="kt">int32_t</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">gmWorkspace</span><span class="p">,</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="kt">int32_t</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">ubWorkspace</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<span id="section622mcpsimp"></span><a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 接口参数说明</p><table><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>gmWorkspace</td><td>输入</td><td>临时空间，通过写gmWorkspace通知其他核当前核已执行完成，其他核可以继续往下执行，类型为GlobalTensor。</td></tr><tr><td>ubWorkspace</td><td>输入</td><td>临时空间，用于操作gmWorkspace，类型为LocalTensor。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<span id="section640mcpsimp"></span><a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<span id="section633mcpsimp"></span><a class="header-anchor" href="#约束说明">​</a></h2><ul><li>要实现确定性计算，需要保证每个核调用NotifyNextBlock/WaitPreBlock接口的次数相同。如果调用了NotifyNextBlock没有与之配对的WaitPreBlock，会导致非确定性计算、输出结果可能不符合预期；如果调用了WaitPreBlock没有与之配对的NotifyNextBlock，会导致程序卡死。</li><li>使用接口前，请确保已经调用<a href="InitDetermineComputeWorkspace.html">InitDetermineComputeWorkspace</a>接口，初始化共享内存。</li><li>gmWorkspace申请的空间最少要求为：GetBlockNum()*32Bytes，ubWorkspace申请的空间最少要求为：GetBlockNum()*32+32Bytes。</li><li>使用该接口进行多核同步时，仅对AIV核生效，WaitPreBlock和NotifyNextBlock之间仅支持插入矢量计算相关指令，对矩阵计算相关指令不生效。</li><li>使用该接口进行多核控制时，算子调用时指定的逻辑AI Core核数numBlocks必须保证不大于实际运行该算子的AI处理器核数，否则框架进行多轮调度时会插入异常同步，导致核函数（Kernel）“卡死”现象。</li></ul><h2 id="调用示例">调用示例<span id="section177231425115410"></span><a class="header-anchor" href="#调用示例">​</a></h2><p>完整样例请参考<a href="InitDetermineComputeWorkspace.html#section177231425115410">调用示例</a>。</p></article></div>`,1)])])}const k=s(i,[["render",n]]);export{_ as __pageData,k as default};
